class MoeImgSource extends ComicSource {
  name = "MoeImg";
  key = "moeimg";
  version = "1.0.3";
  // ComicSource 的默认值为空字符串；当前解析器要求这里是合法的语义版本号。
  minAppVersion = "4.2.11";
  // url 用于远程更新源脚本；未托管脚本时保持为空。
  url = "";

  explore = [
    {
      // explore.title 同时是全局页面标识，必须避免与其他漫画源重复。
      title: "MoeImg",
      type: "multiPageComicList",
      async load(page) {
        return loadComicList(listUrl(page));
      },
    },
  ];

  category = {
    title: "MoeImg 分类",
    parts: MOEIMG_CATEGORY_PARTS,
  };

  categoryComics = {
    optionList: [],
    async load(category, param, options, page) {
      return loadComicList(param == null ? categoryUrl(category, page) : tagUrl(param, page));
    },
  };

  search = {
    optionList: [],
    async load(keyword, searchOptions, page) {
      return loadComicList(searchUrl(keyword, page));
    },
  };

  comic = {
    async loadInfo(id) {
      const doc = await fetchDocument(comicUrl(id));
      const titleElement = first(doc, ".post-single h1.title");
      const title = cleanText(titleElement == null ? "" : titleElement.text);
      const images = extractImages(doc);
      if (title.length === 0 || images.length === 0) {
        throw "未找到作品信息，文章可能已删除或页面结构已变更";
      }

      const descriptionElement = first(doc, ".post-single .description");
      const categoryElement = first(doc, ".post-single .entry-footer .category a");
      const tagElements = doc.querySelectorAll(".post-single .entry-footer .tag a");
      const tags = tagElements.map((element) => cleanText(element.text))
          .filter((tag) => tag.length > 0);
      const category = categoryElement == null ? "" : cleanText(categoryElement.text);

      const tagMap = {};
      if (category.length > 0) {
        tagMap["分类"] = [category];
      }
      if (tags.length > 0) {
        tagMap["标签"] = tags;
      }

      return {
        title: title,
        subTitle: category.length === 0 ? null : category,
        cover: images[0],
        description: descriptionElement == null ? null : cleanText(descriptionElement.text),
        tags: tagMap,
        // 阅读器会无条件使用章节键生成图片缓存键；单图集也必须提供一个章节。
        chapters: { "images": "图片" },
        recommend: [],
      };
    },

    async loadEp(id, ep) {
      const images = extractImages(await fetchDocument(comicUrl(id)));
      if (images.length === 0) {
        throw "未找到可阅读图片，文章可能已删除或页面结构已变更";
      }
      return { images: images };
    },

    // 图片服务器会校验来源页；为正文和缩略图都带上站内 Referer。
    onImageLoad(imageKey, comicId, ep) {
      return { headers: imageHeaders(comicId) };
    },

    onThumbnailLoad(imageKey) {
      return { headers: imageHeaders() };
    },
  };
}

