// 不在分类页展示这些分组，也不会保留它们下属的任何标签。
const MOEIMG_HIDDEN_TAG_GROUPS = [
  "シチュエーション",
  "表情",
  "フェチ",
  "タイプ",
  "キャラクター",
  "閲覧注意",
  "絵師",
  "作品",
  "その他",
];

const MOEIMG_CATEGORY_PARTS = [
  {"name":"主分类","type":"fixed","categories":["エロ画像","非エロ・微エロ画像","閲覧注意画像","ネタ画像"],"itemType":"category"},
].concat(MOEIMG_TAG_GROUPS, MOEIMG_EXTRA_TAG_GROUPS)
    .filter((group) => MOEIMG_HIDDEN_TAG_GROUPS.indexOf(group.name) === -1)
    .map((group) => ({
  name: group.name,
  type: "fixed",
  categories: group.categories,
  itemType: "category",
  categoryParams: group.paths,
}));

const MOEIMG_HOME = "https://moeimg.net/";

function listUrl(page) {
  return page <= 1 ? MOEIMG_HOME : MOEIMG_HOME + "page/" + page;
}

function categoryUrl(category, page) {
  const path = "category/" + encodeURIComponent(category);
  return page <= 1
      ? MOEIMG_HOME + path
      : MOEIMG_HOME + path + "/page/" + page;
}

function tagUrl(tagPath, page) {
  const path = "tag/" + tagPath;
  return page <= 1
      ? MOEIMG_HOME + path
      : MOEIMG_HOME + path + "/page/" + page;
}

function searchUrl(keyword, page) {
  const query = "s=" + encodeURIComponent(keyword);
  return page <= 1
      ? MOEIMG_HOME + "?" + query
      : MOEIMG_HOME + "page/" + page + "?" + query;
}

function comicUrl(id) {
  return MOEIMG_HOME + id + ".html";
}

function imageHeaders(comicId) {
  return {
    Referer: comicId == null ? MOEIMG_HOME : comicUrl(comicId),
  };
}

async function fetchDocument(url) {
  const response = await Network.get(url, { Referer: MOEIMG_HOME });
  if (response.status == null || response.status < 200 || response.status >= 400) {
    throw "请求失败: " + (response.status == null ? "网络错误" : response.status);
  }
  return new HtmlDocument(response.body);
}

async function loadComicList(url) {
  const doc = await fetchDocument(url);
  return {
    comics: extractComics(doc),
    // 网站只给出相邻页，无法可靠取得最后一页；null 让应用按实际空页停止加载。
    maxPage: null,
  };
}

function extractComics(doc) {
  const comics = [];
  const items = doc.querySelectorAll(".post-field");
  for (const item of items) {
    const titleLink = first(item, ".post-field-right h2.title a");
    const coverElement = first(item, ".post-field-left img.thumbnail_image");
    if (titleLink == null || coverElement == null) {
      continue;
    }

    const href = titleLink.attributes["href"];
    const id = comicIdFromUrl(href);
    const cover = coverElement.attributes["src"];
    if (id == null || cover == null) {
      continue;
    }

    const categoryElement = first(item, ".blog-info-h .cat a");
    const tagElements = item.querySelectorAll(".blog-info-f .tag a");
    const tags = tagElements.map((element) => cleanText(element.text))
        .filter((tag) => tag.length > 0);
    const category = categoryElement == null ? "" : cleanText(categoryElement.text);

    comics.push({
      id: id,
      title: cleanText(titleLink.text),
      subTitle: category.length === 0 ? null : category,
      cover: cover,
      tags: tags,
    });
  }
  return comics;
}

function extractImages(doc) {
  const images = [];
  const elements = doc.querySelectorAll(".post-single img.thumbnail_image");
  for (const element of elements) {
    const src = element.attributes["src"];
    // 正文图片均保存在 /wp-content/uploads/archives*/ 下；该规则会排除站内广告和相关推荐缩略图。
    if (src != null && src.indexOf("/wp-content/uploads/archives") >= 0) {
      images.push(src);
    }
  }
  return images;
}

function comicIdFromUrl(url) {
  if (url == null) {
    return null;
  }
  const matched = url.match(/\/(\d+)\.html(?:[?#]|$)/);
  return matched == null ? null : matched[1];
}

function cleanText(text) {
  return (text == null ? "" : text).replace(/\s+/g, " ").trim();
}

// HtmlDocument.querySelector() 会把内部元素索引 0 错当成未匹配；统一由 querySelectorAll 取首项。
function first(element, selector) {
  const elements = element.querySelectorAll(selector);
  return elements.length === 0 ? null : elements[0];
}
